function minimumDifference(nums, k) {
  let best = Infinity;
  let ors = [];

  for (const num of nums) {
    const next = [num];
    for (const value of ors) {
      const merged = value | num;
      if (merged !== next[next.length - 1]) {
        next.push(merged);
      }
    }
    for (const value of next) {
      best = Math.min(best, Math.abs(k - value));
    }
    ors = next;
  }
  return best;
}

