function minimumDifference(nums, k) {
  let answer = null;
  for (let l = 0; l < nums.length; l++) {
    let total = 0;
    for (let r = l; r < nums.length; r++) {
      total = total | nums[r];
      const gap = total > k ? total - k : k - total;
      if (answer === null || gap < answer) answer = gap;
    }
  }
  return answer;
}

