function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const style = Math.floor(rand() * 3);
    const nums = Array.from({ length: n }, () => {
      if (style === 0) return pick(1, 1000000000);
      if (style === 1) return 1 << pick(0, 29);
      let value = 0;
      for (let b = 0; b < 2; b++) value |= 1 << pick(0, 29);
      return value;
    });
    return [nums, pick(1, 1000000000)];
  }
  const n = pick(1, 8);
  const top = rand() < 0.5 ? 15 : 63;
  const nums = Array.from({ length: n }, () => pick(1, top));
  return [nums, pick(1, top + 10)];
}
